//! Qualification inputs only. No fixture is a production trust source.

use super::*;
use codex_hepta_contracts::AuthorityFrontierStore;
use codex_hepta_contracts::AuthorityTrustError;
use codex_hepta_contracts::FinalUseFrontier;
use codex_hepta_contracts::FinalUseIssuerTrustKey;
use codex_hepta_contracts::FinalUseRevocations;
use codex_hepta_contracts::Sha256Digest;
use codex_hepta_fleet::AgentLifecycle;
use codex_hepta_fleet::AgentManifest;
use codex_hepta_fleet::FleetRegistry;
use codex_hepta_fleet::ResourceBudget;
use codex_hepta_fleet::WorkspaceBinding;
use codex_hepta_memory::CognitiveRecoveryAnchor;
use codex_hepta_memory::CognitiveStore;
use codex_hepta_memory::ProductionAuthorityToken;
use codex_hepta_memory::ProductionDispatchFuture;
use codex_hepta_memory::ProductionDispatchRequest;
use codex_hepta_memory::ProductionOutboxTarget;
use codex_hepta_memory::ProductionTargetOutcome;
use codex_hepta_paths::HeptaFleetRoot;
use ed25519_dalek::SigningKey;
use std::collections::BTreeSet;
use std::error::Error;
use std::fs;
use std::os::unix::fs::PermissionsExt;
use std::sync::Mutex;
use std::sync::atomic::AtomicBool;
use std::sync::atomic::AtomicU64;
use std::sync::atomic::AtomicUsize;
use std::sync::atomic::Ordering;

pub(super) const EXPIRES: u64 = 4_000_000_000;
pub(super) const LIVE_MS: u64 = 2_000_000_000_000;

pub(super) struct Clock {
    pub now_ms: AtomicU64,
    pub unavailable: AtomicBool,
    pub calls: AtomicUsize,
}

impl AuthorityClock for Clock {
    fn now_unix_ms(&self) -> Result<u64, AuthorityTrustError> {
        self.calls.fetch_add(1, Ordering::SeqCst);
        if self.unavailable.load(Ordering::SeqCst) {
            return Err(AuthorityTrustError::Unavailable);
        }
        Ok(self.now_ms.load(Ordering::SeqCst))
    }
}

pub(super) struct Verifier {
    pub calls: AtomicUsize,
    pub expire_at_call: AtomicUsize,
    pub unavailable_at_call: AtomicUsize,
    pub reject_at_call: AtomicUsize,
    clock: Arc<Clock>,
}

impl ProductionAuthorityVerifier for Verifier {
    fn verify(
        &self,
        authority: &ProductionAuthorityLease,
        expected: &AgentId,
    ) -> Result<(), String> {
        let call = self.calls.fetch_add(1, Ordering::SeqCst) + 1;
        if &authority.agent_id != expected
            || authority.grant_digest != Sha256Digest::for_bytes(b"composition-fixture")
            || call == self.reject_at_call.load(Ordering::SeqCst)
        {
            return Err("fixture original verifier rejected authority".to_string());
        }
        if call == self.expire_at_call.load(Ordering::SeqCst) {
            self.clock.now_ms.store(EXPIRES * 1_000, Ordering::SeqCst);
        }
        if call == self.unavailable_at_call.load(Ordering::SeqCst) {
            self.clock.unavailable.store(true, Ordering::SeqCst);
        }
        Ok(())
    }
}

pub(super) struct Frontier {
    head: FinalUseFrontier,
    pub denied: AtomicBool,
    pub loads: AtomicUsize,
}

impl AuthorityFrontierStore<FinalUseFrontier> for Frontier {
    fn load(&self, owner: &str) -> Result<FinalUseFrontier, AuthorityTrustError> {
        self.loads.fetch_add(1, Ordering::SeqCst);
        if owner != "composition-fixture-issuer" || self.denied.load(Ordering::SeqCst) {
            return Err(AuthorityTrustError::Unavailable);
        }
        Ok(self.head)
    }

    fn compare_and_set(
        &self,
        _owner: &str,
        _expected: &FinalUseFrontier,
        _next: &FinalUseFrontier,
    ) -> Result<(), AuthorityTrustError> {
        // Bootstrap must never claim a grant or mutate the external frontier.
        Err(AuthorityTrustError::Unavailable)
    }
}

pub(super) struct Target {
    pub metadata_calls: AtomicUsize,
    pub effects: AtomicUsize,
    pub late_clock_fault: AtomicUsize,
    pub ack_failure: Mutex<Option<AckFailure>>,
    clock: Arc<Clock>,
    verifier: Arc<Verifier>,
}

pub(super) struct AckFailure {
    pub socket: UnixDatagram,
    pub observed: Option<serde_json::Value>,
    pub fault: usize,
}

impl ProductionOutboxTarget for Target {
    fn dispatch<'a>(&'a self, _request: ProductionDispatchRequest) -> ProductionDispatchFuture<'a> {
        self.effects.fetch_add(1, Ordering::SeqCst);
        Box::pin(async {
            ProductionTargetOutcome::Rejected {
                reason: "bootstrap fixture never permits an effect".to_string(),
            }
        })
    }
}

impl FinalUseProductionOutboxTarget for Target {
    fn destination_id(&self) -> &str {
        self.metadata_calls.fetch_add(1, Ordering::SeqCst);
        if let Some(probe) = self.ack_failure.lock().unwrap().as_mut() {
            let mut bytes = [0_u8; 1024];
            match probe.socket.recv(&mut bytes) {
                Ok(length) => {
                    probe.observed = Some(serde_json::from_slice(&bytes[..length]).unwrap());
                    match probe.fault {
                        1 => self.clock.now_ms.store(EXPIRES * 1_000, Ordering::SeqCst),
                        2 => self.clock.unavailable.store(true, Ordering::SeqCst),
                        _ => self.verifier.reject_at_call.store(
                            self.verifier.calls.load(Ordering::SeqCst) + 1,
                            Ordering::SeqCst,
                        ),
                    }
                }
                Err(error) if error.kind() == std::io::ErrorKind::WouldBlock => {}
                result => panic!("unexpected fixture ACK observation: {result:?}"),
            }
        }
        // Preflight is original verifier call 1. Later metadata validation
        // occurs only after recovery's live authority checks have run.
        if self.verifier.calls.load(Ordering::SeqCst) > 1 {
            match self.late_clock_fault.load(Ordering::SeqCst) {
                1 => self.clock.now_ms.store(EXPIRES * 1_000, Ordering::SeqCst),
                2 => self.clock.unavailable.store(true, Ordering::SeqCst),
                _ => {}
            }
        }
        "composition-fixture-target"
    }
}

pub(super) struct Probes {
    pub clock: Arc<Clock>,
    pub verifier: Arc<Verifier>,
    pub target: Arc<Target>,
    pub frontier: Arc<Frontier>,
}

pub(super) struct Fixture {
    // An opt-in real-provider fixture keeps this original owner for reconciliation.
    pub(super) directory: tempfile::TempDir,
    next_inputs: AtomicUsize,
    pub cut: CognitiveRecoveryAnchor,
    authority: ProductionAuthorityLease,
}

impl Fixture {
    pub async fn new() -> Result<(AgentdConfig, Self), Box<dyn Error>> {
        let directory = tempfile::tempdir()?;
        let root = directory.path().canonicalize()?;
        fs::set_permissions(&root, fs::Permissions::from_mode(0o700))?;
        let fleet_path = root.join("fleet");
        let fleet = HeptaFleetRoot::parse(fleet_path.clone())?;
        let registry = FleetRegistry::initialize(fleet.clone())?;
        let workspace = root.join("workspace");
        fs::create_dir(&workspace)?;
        let owner = AgentId::parse("00000000-0000-4000-8000-00000000c062")?;
        let record = registry.register(AgentManifest::new(
            owner.clone(),
            WorkspaceBinding::new(workspace.clone(), &fleet)?,
            ResourceBudget::local_default(),
        )?)?;
        registry.compare_and_transition(&owner, 0, AgentLifecycle::Starting)?;
        let config = AgentdConfig::load(
            fleet_path,
            owner.clone(),
            1,
            record.layout.home_root().to_path_buf(),
            record.layout.run_root().to_path_buf(),
            record.layout.home_root().to_path_buf(),
            workspace,
        )?;
        // Qualification-only genesis. The product API accepts only an
        // independently retained current cut and never captures one itself.
        let store = CognitiveStore::open(&config.identity().layout).await?;
        let cut = store.recovery_anchor().await?;
        store.close().await;
        let authority = ProductionAuthorityLease::from_verified_parts(
            owner,
            Sha256Digest::for_bytes(b"composition-fixture"),
            13,
            17,
            EXPIRES,
            ProductionAuthorityToken::from_verified_bytes(b"composition-fixture-token".to_vec())?,
        )?;
        Ok((
            config,
            Self {
                directory,
                next_inputs: AtomicUsize::new(0),
                cut,
                authority,
            },
        ))
    }

    pub fn inputs(
        &self,
    ) -> Result<(AgentdProductionHostInputs<'_>, Probes, UnixStream), Box<dyn Error>> {
        let state_directory = self.directory.path().join(format!(
            "final-use-{}",
            self.next_inputs.fetch_add(1, Ordering::SeqCst)
        ));
        fs::create_dir(&state_directory)?;
        fs::set_permissions(&state_directory, fs::Permissions::from_mode(0o700))?;
        let head = FinalUseRevocations {
            authority_epoch: 19,
            revision: 1,
            revoked_grant_ids: BTreeSet::new(),
        };
        let clock = Arc::new(Clock {
            now_ms: AtomicU64::new(LIVE_MS),
            unavailable: AtomicBool::new(false),
            calls: AtomicUsize::new(0),
        });
        let verifier = Arc::new(Verifier {
            calls: AtomicUsize::new(0),
            expire_at_call: AtomicUsize::new(0),
            unavailable_at_call: AtomicUsize::new(0),
            reject_at_call: AtomicUsize::new(0),
            clock: clock.clone(),
        });
        let target = Arc::new(Target {
            metadata_calls: AtomicUsize::new(0),
            effects: AtomicUsize::new(0),
            late_clock_fault: AtomicUsize::new(0),
            ack_failure: Mutex::new(None),
            clock: clock.clone(),
            verifier: verifier.clone(),
        });
        let frontier = Arc::new(Frontier {
            head: FinalUseFrontier::for_initial_head(&head)?,
            denied: AtomicBool::new(false),
            loads: AtomicUsize::new(0),
        });
        let (issuer_stream, peer) = UnixStream::pair()?;
        let inputs = AgentdProductionHostInputs {
            current_cut: CognitiveRecoveryRequirement::ExactCurrentCut(&self.cut),
            authority: self.authority.clone(),
            verifier: verifier.clone(),
            lease_id: "composition-fixture-lease".to_string(),
            lease_generation: 1,
            final_use: AgentdFinalUseHostInputs {
                state_directory,
                signer_id: "composition-fixture-issuer".to_string(),
                issuer_keys: vec![FinalUseIssuerTrustKey {
                    key_id: "fixture-only".to_string(),
                    verifying_key: SigningKey::from_bytes(&[61; 32]).verifying_key().to_bytes(),
                    not_before_authority_epoch: 19,
                    not_after_authority_epoch: 19,
                }],
                revocations: head,
                clock: clock.clone(),
                frontier_store: frontier.clone(),
            },
            issuer_stream,
            issuer_peer: AgentdFinalUseIssuerPeer {
                // SAFETY: geteuid has no preconditions and only reads process identity.
                uid: unsafe { libc::geteuid() },
                pid: std::process::id(),
            },
            issuer_timeout: Duration::from_secs(1),
            target: target.clone(),
            reconcile_interval: Duration::from_millis(20),
            notes: None,
        };
        Ok((
            inputs,
            Probes {
                clock,
                verifier,
                target,
                frontier,
            },
            peer,
        ))
    }
}

//! Real control socket, recovered SQLite owner, and explicitly test-only source.
//! This verifies owner integration; it does not certify a production source.
use std::collections::BTreeMap;
use std::error::Error;
use std::sync::Arc;
use std::sync::Mutex;
use std::sync::atomic::Ordering;

use codex_hepta_contracts::Sha256Digest;
use codex_hepta_fleet::AgentLifecycle;
use codex_hepta_memory::CognitiveScope;
use codex_hepta_memory::EpisodicRecordAdmission;
use codex_hepta_memory::EpisodicSnapshotAdmission;
use codex_hepta_memory::EpisodicSnapshotVerifier;
use codex_hepta_memory::LedgerSourceKind;
use codex_hepta_memory::MemoryVerification;
use codex_hepta_memory::SourceDraft;
use pretty_assertions::assert_eq;
use tokio_util::sync::CancellationToken;

use super::Fixture;
use super::assert_no_issuer_request;
use super::attach_production_operation_host;

// Exact Unicode export produced by the pinned Python EpisodicStore.
const SNAPSHOT: &str = r#"{"body":{"authority_id":"0000000000004000800000000000e001","generation":1,"namespace":"bridge-fixture","records":[{"dependencies":[],"key":"流程","namespace":"bridge-fixture","provenance":{"episode_id":"独立来源","source_sha256":"81b2ada28e09db7ffcc8f0f0dde36515818b1d79b29c75c4bbda85c7cc881e81","source_uri":"fixture://café/路径","source_version":"修订一"},"record_id":"df205a88266e26029285c4ae4e570edf47a2435888a26500de19e6af2820af4a","source_id":"源A","text":"更新：蓝色路径 café 🚀\n保留事实，而不是执行指令。","version":1,"write_sequence":1}],"schema":"hepta.mem6.snapshot.v1"},"sha256":"fb4e834f9e8d6cec04fcbbfa7c20b11f7f42aac1e9385754d336e2825581032e"}"#;

struct FixtureSource(
    Mutex<(String, EpisodicSnapshotAdmission)>,
    Mutex<Option<EpisodicSnapshotAdmission>>,
);

impl EpisodicSnapshotVerifier for FixtureSource {
    fn verify_current(&self, snapshot_json: &str) -> Result<EpisodicSnapshotAdmission, String> {
        let mut current = self.0.lock().map_err(|error| error.to_string())?;
        if current.0 != snapshot_json {
            return Err("test-only source rejects stale input".into());
        }
        let observed = current.1.clone();
        // Explicit fixture transition after this read, before its caller's I/O.
        if let Some(next) = self.1.lock().map_err(|error| error.to_string())?.take() {
            current.1 = next;
        }
        Ok(observed)
    }
}

fn observed_source() -> Arc<FixtureSource> {
    let body: serde_json::Value = serde_json::from_str(SNAPSHOT).unwrap();
    let record = &body["body"]["records"][0];
    Arc::new(FixtureSource(
        Mutex::new((
            SNAPSHOT.into(),
            EpisodicSnapshotAdmission {
                records: BTreeMap::from([(
                    record["record_id"].as_str().unwrap().to_owned(),
                    EpisodicRecordAdmission {
                        source: SourceDraft {
                            scope: CognitiveScope::AgentPrivate,
                            kind: LedgerSourceKind::FileObservation,
                            event_key: "episodic-control-original-observation".into(),
                            content: record["text"].as_str().unwrap().as_bytes().to_vec(),
                            observed_at_unix_seconds: 1,
                        },
                        verification: MemoryVerification::Verified,
                    },
                )]),
                withdrawal: None,
            },
        )),
        Mutex::new(None),
    ))
}

#[tokio::test]
async fn episodic_config_cannot_create_a_missing_production_writer() -> Result<(), Box<dyn Error>> {
    let (config, _fixture) = Fixture::new().await?;
    let error = config
        .with_episodic_snapshot_import("bridge-fixture".into(), observed_source())
        .err()
        .expect("original writer is required");
    assert!(matches!(
        error,
        crate::AgentdError::CognitiveWriteRuntimeUnavailable
    ));
    Ok(())
}

#[tokio::test]
async fn episodic_control_replays_original_commit_then_rejects_revoked_context()
-> Result<(), Box<dyn Error>> {
    let (mut config, fixture) = Fixture::new().await?;
    let (inputs, probes, peer) = fixture.inputs()?;
    attach_production_operation_host(&mut config, inputs).await?;
    let host = config.production_writer_host().unwrap();
    let source = observed_source();
    let mut config =
        config.with_episodic_snapshot_import("bridge-fixture".into(), source.clone())?;
    let ingress = config.take_episodic_snapshot_import().unwrap();
    let (identity, registry, _writer_lock) = config.into_parts();
    let state = Arc::new(crate::state::AgentdState::new(
        identity.clone(),
        registry.clone(),
        /*event_capacity*/ 32,
    )?);
    state.attach_cognitive_store(host.cognitive_runtime().available_store().unwrap().clone())?;
    state
        .episodic_snapshot_import
        .set(ingress)
        .ok()
        .expect("single owner");
    let running =
        registry.compare_and_transition(&identity.agent_id, 1, AgentLifecycle::Running)?;
    state.refresh_generation()?;
    state.mark_runtime_prerequisites_ready()?;
    state.mark_app_server_ready()?;
    // The model profile drops its mutation handle while the original control
    // owner below still commits, reconciles, reads, and withdraws real rows.
    assert!(host.production_mutation().is_some());
    let options = crate::app_runtime::app_server_runtime_options_for_agent(
        &identity,
        state.clone(),
        host.cognitive_runtime(),
        host.production_mutation(),
        crate::app_runtime::AppServerModelToolProfile::ExplicitContextOnly,
    )?;
    assert!(options.hepta_cognitive_production_mutation.is_none());
    assert!(Arc::ptr_eq(
        options.hepta_cognitive_runtime.available_store().unwrap(),
        host.cognitive_runtime().available_store().unwrap(),
    ));
    assert_eq!(
        options.required_feature_states,
        BTreeMap::from([
            (codex_features::Feature::HeptaCognitiveWrite, false),
            (codex_features::Feature::HeptaMemory, false),
            (codex_features::Feature::MemoryTool, false),
            (codex_features::Feature::TokenBudget, false),
        ]),
    );
    let cancellation = CancellationToken::new();
    let server = crate::AgentdControlServer::bind(
        identity.control_socket.clone(),
        state,
        cancellation.clone(),
    )
    .await?;
    let server_task = tokio::spawn(server.run());
    let first = crate::AgentdClient::new(
        identity.control_socket.clone(),
        identity.agent_id.clone(),
        /*spawn_generation*/ 1,
    )?;
    // A fresh configured process has no current source observation, even if
    // native context would otherwise be empty. Reconciliation opens this path.
    let before = host.writer().recovery_anchor().await?;
    assert!(
        first
            .cognitive_context("café".into(), /*limit*/ 4)
            .await
            .is_err()
    );
    assert_eq!(host.writer().recovery_anchor().await?, before);
    let wrong_namespace = SNAPSHOT.replace("bridge-fixture", "another-namespace");
    assert!(
        first
            .import_episodic_snapshot(wrong_namespace)
            .await
            .is_err()
    );
    let committed = first.import_episodic_snapshot(SNAPSHOT.into()).await?;
    let cut = host.writer().recovery_anchor().await?;
    assert_eq!(
        first.import_episodic_snapshot(SNAPSHOT.into()).await?,
        committed
    );
    assert_eq!(host.writer().recovery_anchor().await?, cut);
    assert_eq!(
        (committed.active_records, committed.retired_records),
        (1, 0)
    );

    // A separate control client uses the ordinary canonical context path.
    let next = crate::AgentdClient::new(
        identity.control_socket.clone(),
        identity.agent_id.clone(),
        /*spawn_generation*/ 1,
    )?;
    let context = next.cognitive_context("café".into(), /*limit*/ 4).await?;
    assert_eq!(context.items.len(), 1);
    assert_eq!(
        next.revalidate_cognitive_context(&context)
            .await?
            .verified_item_count,
        1
    );
    let original = source.0.lock().unwrap().1.clone();
    let mut metadata_changed = original.clone();
    metadata_changed
        .records
        .values_mut()
        .next()
        .unwrap()
        .source
        .event_key
        .push_str("-changed");
    let mut provisional = original.clone();
    provisional
        .records
        .values_mut()
        .next()
        .unwrap()
        .verification = MemoryVerification::Provisional;
    // Independent source changes with byte-identical facts do not reuse the
    // previously Verified canonical cut. Reset only the test fixture between cases.
    for changed in [metadata_changed.clone(), provisional] {
        source.0.lock().unwrap().1 = changed;
        assert!(
            next.cognitive_context("café".into(), /*limit*/ 4)
                .await
                .is_err()
        );
        assert!(next.revalidate_cognitive_context(&context).await.is_err());
        assert_eq!(host.writer().recovery_anchor().await?, cut);
        source.0.lock().unwrap().1 = original.clone();
    }
    // The first source check succeeds, then the fixture changes before the
    // owner async read. Publication and final revalidation must check again.
    *source.1.lock().unwrap() = Some(metadata_changed.clone());
    assert!(
        next.cognitive_context("café".into(), /*limit*/ 4)
            .await
            .is_err()
    );
    source.0.lock().unwrap().1 = original.clone();
    *source.1.lock().unwrap() = Some(metadata_changed);
    assert!(next.revalidate_cognitive_context(&context).await.is_err());
    assert_eq!(host.writer().recovery_anchor().await?, cut);
    source.0.lock().unwrap().1 = original;
    let body = r#"{"authority_id":"0000000000004000800000000000e001","generation":2,"namespace":"bridge-fixture","records":[],"schema":"hepta.mem6.snapshot.v1"}"#;
    let withdrawn = format!(
        r#"{{"body":{body},"sha256":"{}"}}"#,
        Sha256Digest::for_bytes(body.as_bytes()).as_str()
    );
    *source.0.lock().unwrap() = (
        withdrawn.clone(),
        EpisodicSnapshotAdmission {
            records: BTreeMap::new(),
            withdrawal: Some(SourceDraft {
                scope: CognitiveScope::AgentPrivate,
                kind: LedgerSourceKind::ExplicitMemoryDirective,
                event_key: "episodic-control-original-withdrawal".into(),
                content: b"The source owner withdrew this fact.".to_vec(),
                observed_at_unix_seconds: 2,
            }),
        },
    );
    // External revocation alone must close reads before any native tombstone
    // is imported. The refused reads do not mutate the canonical owner.
    assert!(
        next.cognitive_context("café".into(), /*limit*/ 4)
            .await
            .is_err()
    );
    assert!(next.revalidate_cognitive_context(&context).await.is_err());
    assert_eq!(host.writer().recovery_anchor().await?, cut);
    assert!(
        next.import_episodic_snapshot(SNAPSHOT.into())
            .await
            .is_err()
    );
    assert_eq!(host.writer().recovery_anchor().await?, cut);
    let removed = next.import_episodic_snapshot(withdrawn.clone()).await?;
    assert_eq!((removed.active_records, removed.retired_records), (0, 1));
    assert!(
        next.cognitive_context("café".into(), /*limit*/ 4)
            .await?
            .items
            .is_empty()
    );
    assert!(next.revalidate_cognitive_context(&context).await.is_err());
    let cut = host.writer().recovery_anchor().await?;
    registry.compare_and_transition(
        &identity.agent_id,
        running.generation,
        AgentLifecycle::Draining,
    )?;
    assert!(next.import_episodic_snapshot(withdrawn).await.is_err());
    assert_eq!(host.writer().recovery_anchor().await?, cut);
    assert_eq!(probes.target.effects.load(Ordering::SeqCst), 0);
    assert_no_issuer_request(peer)?;
    cancellation.cancel();
    server_task.await??;
    Ok(())
}

#[tokio::test]
async fn episodic_wire_without_configured_source_cannot_mutate_original_owner()
-> Result<(), Box<dyn Error>> {
    let (mut config, fixture) = Fixture::new().await?;
    let (inputs, probes, peer) = fixture.inputs()?;
    attach_production_operation_host(&mut config, inputs).await?;
    let host = config
        .production_writer_host()
        .expect("original recovered writer");
    let before = host.writer().recovery_anchor().await?;
    let (identity, registry, _writer_lock) = config.into_parts();
    let state = Arc::new(crate::state::AgentdState::new(
        identity.clone(),
        registry.clone(),
        /*event_capacity*/ 32,
    )?);
    state.attach_cognitive_store(host.cognitive_runtime().available_store().unwrap().clone())?;
    registry.compare_and_transition(
        &identity.agent_id,
        /*expected_generation*/ 1,
        AgentLifecycle::Running,
    )?;
    state.refresh_generation()?;
    state.mark_runtime_prerequisites_ready()?;
    state.mark_app_server_ready()?;
    let cancellation = CancellationToken::new();
    let server = crate::AgentdControlServer::bind(
        identity.control_socket.clone(),
        state,
        cancellation.clone(),
    )
    .await?;
    let server_task = tokio::spawn(server.run());
    let client = crate::AgentdClient::new(
        identity.control_socket.clone(),
        identity.agent_id.clone(),
        /*spawn_generation*/ 1,
    )?;
    let error = client
